-- Synthetic-only pgTAP against the final seven AI functions plus the reviewed personal-owner DRAFT.
-- Run exclusively inside an authorized isolated fixture; the entire suite rolls back.
begin;
select plan(124);
create function pg_temp.po_id(n integer) returns uuid language sql immutable as $$select ('aa050000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,instance_id,aud,role,email) select pg_temp.po_id(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','personal-owner-'||n||'@test.invalid' from generate_series(1,8)n;
insert into public.profiles(id,role,name) select pg_temp.po_id(n),case n when 1 then 'admin' when 4 then 'staff' when 5 then 'viewer' else 'teacher' end,'Synthetic personal owner '||n from generate_series(1,8)n on conflict(id) do update set role=excluded.role;
update auth.users set banned_until=clock_timestamp()+interval '1 day' where id=pg_temp.po_id(7);
update auth.users set deleted_at=clock_timestamp() where id=pg_temp.po_id(8);
update public.profiles set name=null where id=pg_temp.po_id(6);
create temp table po_evidence(k text primary key,v jsonb not null);
grant all on po_evidence to authenticated,service_role;
update dashboard_private.ai_agent_chat_support set issuance_enabled=true where singleton;
update dashboard_private.chat_space_configuration set configured=true,resource_name='spaces/PERSONAL_owner_space',public_origin='https://dashboard.test.invalid' where space_key='space_1';
insert into dashboard_private.chat_user_space_permissions(user_id,space_keys,configured_by) values(pg_temp.po_id(2),array['space_1'],pg_temp.po_id(1)),(pg_temp.po_id(3),array['space_1'],pg_temp.po_id(1));
create function pg_temp.po_issue(owner_number integer,key_number integer) returns jsonb language sql as $$select public.ai_agent_personal_credential_api_v1('create',jsonb_build_object('ownerProfileId',pg_temp.po_id(owner_number),'label','Synthetic teacher AI','scopes',jsonb_build_array('ai-agent:requests:read','ai-agent:requests:claim','ai-agent:requests:update','chat:outbox:read','chat:send'),'grant',jsonb_build_object('queues',jsonb_build_array('employee_requests'),'actions',jsonb_build_array('read','claim','renew','progress','question','done'),'spaceKeys',jsonb_build_array('space_1'),'purposes',jsonb_build_array('ai_completion')),'expiresAt',null,'idempotencyKey',pg_temp.po_id(key_number)))$$;
create function pg_temp.po_hash(label text) returns text language sql as $$select encode(sha256(convert_to(v->>'token','UTF8')),'hex') from po_evidence where k=label$$;
create function pg_temp.po_bot(label text,action text,input jsonb default '{}') returns jsonb language sql as $$select public.ai_agent_bot_api_v1(pg_temp.po_hash(label),action,input)$$;
create function pg_temp.po_chat(label text,action text,input jsonb default '{}') returns jsonb language sql as $$select public.ai_agent_chat_api_v1(pg_temp.po_hash(label),action,input)$$;
create function pg_temp.po_request(label text) returns uuid language sql as $$select (v->>'id')::uuid from po_evidence where k=label$$;
create function pg_temp.po_item(label text,inventory text) returns jsonb language sql as $$select item from po_evidence e cross join lateral jsonb_array_elements(e.v->'items') item where e.k=inventory and item->>'id'=(select v->>'id' from po_evidence where k=label)$$;
create function pg_temp.po_claim_input(label text,key_number integer,version text default '1') returns jsonb language sql as $$select jsonb_build_object('id',pg_temp.po_request(label),'version',version,'idempotencyKey',pg_temp.po_id(key_number),'claimTokenHash',repeat('a',64))$$;
create function pg_temp.po_update_input(key_number integer) returns jsonb language sql as $$select jsonb_build_object('id',pg_temp.po_request('own'),'version',(select version::text from dashboard_private.ai_agent_requests where id=pg_temp.po_request('own')),'idempotencyKey',pg_temp.po_id(key_number),'claimTokenHash',repeat('a',64),'claimGeneration',(select generation::text from dashboard_private.ai_agent_request_claims where request_id=pg_temp.po_request('own')))$$;
-- This test-only helper reads private state as the fixture owner, without changing JWT identity.
alter function pg_temp.po_update_input(integer) security definer;

select set_config('request.jwt.claim.sub',pg_temp.po_id(1)::text,true);
set local role authenticated;
insert into po_evidence values('owners',public.ai_agent_personal_credential_api_v1('owners','{"page":1,"pageSize":20}'));
select is((select v->>'total' from po_evidence where k='owners'),'3','owner picker includes only active current teachers');
select is((select v->>'page' from po_evidence where k='owners'),'1','owner picker echoes the requested page');
select is((select v->>'pageSize' from po_evidence where k='owners'),'20','owner picker echoes the requested page size');
select is(jsonb_array_length((select v->'items' from po_evidence where k='owners')),3,'owner picker returns a nonempty eligible page');
select ok((select bool_and(item-'id'-'name'='{}'::jsonb and item ? 'id' and item ? 'name') from po_evidence e cross join lateral jsonb_array_elements(e.v->'items') item where e.k='owners'),'owner candidates expose exactly ID and display name');
select is((select item->'name' from po_evidence e cross join lateral jsonb_array_elements(e.v->'items') item where e.k='owners' and item->>'id'=pg_temp.po_id(6)::text),'null'::jsonb,'nullable teacher display name is represented as JSON null');
select is(public.ai_agent_personal_credential_api_v1('owners','{}')->>'pageSize','10','owner picker uses the agreed default page size');
select throws_ok($q$select public.ai_agent_personal_credential_api_v1('owners','{"role":"teacher"}')$q$,'22023','ai_agent_invalid','owner enumeration rejects caller-selected filters');
select throws_ok($q$select public.ai_agent_personal_credential_api_v1('owners','{"page":0}')$q$,'22023','ai_agent_invalid','owner enumeration rejects a page before the first');
select throws_ok($q$select public.ai_agent_personal_credential_api_v1('owners','{"page":10001}')$q$,'22023','ai_agent_invalid','owner enumeration enforces the upper page bound');
select throws_ok($q$select public.ai_agent_personal_credential_api_v1('owners','{"pageSize":11}')$q$,'22023','ai_agent_invalid','owner enumeration accepts only supported page sizes');
select throws_ok($q$select public.ai_agent_personal_credential_api_v1('owners','{"page":"1"}')$q$,'22023','ai_agent_invalid','owner enumeration rejects string pagination');
select throws_ok($q$select public.ai_agent_personal_credential_api_v1('owners','{"page":null}')$q$,'22023','ai_agent_invalid','owner enumeration rejects null pagination');
reset role;
update public.profiles set role='viewer' where id=pg_temp.po_id(6);
set local role authenticated;
select is(public.ai_agent_personal_credential_api_v1('owners','{}')->>'total','2','owner picker immediately excludes a changed teacher role');
reset role;
update public.profiles set role='teacher' where id=pg_temp.po_id(6);
update auth.users set banned_until=clock_timestamp()+interval '1 day' where id=pg_temp.po_id(6);
set local role authenticated;
select is(public.ai_agent_personal_credential_api_v1('owners','{}')->>'total','2','owner picker immediately excludes a current auth ban');
reset role;
update auth.users set banned_until=null,deleted_at=clock_timestamp() where id=pg_temp.po_id(6);
set local role authenticated;
select is(public.ai_agent_personal_credential_api_v1('owners','{}')->>'total','2','owner picker immediately excludes current deletion');
reset role;
update auth.users set deleted_at=null where id=pg_temp.po_id(6);
update public.profiles set role='viewer' where id=pg_temp.po_id(1);
set local role authenticated;
select throws_ok($q$select public.ai_agent_personal_credential_api_v1('owners','{}')$q$,'42501','ai_agent_forbidden','owner enumeration rechecks the current admin role');
reset role;
update public.profiles set role='admin' where id=pg_temp.po_id(1);
update auth.users set banned_until=clock_timestamp()+interval '1 day' where id=pg_temp.po_id(1);
set local role authenticated;
select throws_ok($q$select public.ai_agent_personal_credential_api_v1('owners','{}')$q$,'42501','ai_agent_forbidden','owner enumeration rechecks current admin auth ban');
reset role;
update auth.users set banned_until=null,deleted_at=clock_timestamp() where id=pg_temp.po_id(1);
set local role authenticated;
select throws_ok($q$select public.ai_agent_personal_credential_api_v1('owners','{}')$q$,'42501','ai_agent_forbidden','owner enumeration rechecks current admin deletion');
reset role;
update auth.users set deleted_at=null where id=pg_temp.po_id(1);
-- More than twenty eligible synthetic teachers exercise real bounded pagination.
insert into auth.users(id,instance_id,aud,role,email) select pg_temp.po_id(n),'00000000-0000-0000-0000-000000000000','authenticated','authenticated','personal-selector-'||n||'@test.invalid' from generate_series(50,70)n;
insert into public.profiles(id,role,name) select pg_temp.po_id(n),'teacher','Selector fixture '||lpad(n::text,2,'0') from generate_series(50,70)n;
set local role authenticated;
insert into po_evidence values('owners_page1',public.ai_agent_personal_credential_api_v1('owners','{"page":1,"pageSize":10}')),('owners_page2',public.ai_agent_personal_credential_api_v1('owners','{"page":2,"pageSize":10}')),('owners_page3',public.ai_agent_personal_credential_api_v1('owners','{"page":3,"pageSize":10}'));
select is((select v->>'total' from po_evidence where k='owners_page1'),'24','owner picker total counts the same eligible population as pages');
select is(jsonb_array_length((select v->'items' from po_evidence where k='owners_page1')),10,'first owner page is bounded');
select is(jsonb_array_length((select v->'items' from po_evidence where k='owners_page2')),10,'second owner page is bounded');
select is(jsonb_array_length((select v->'items' from po_evidence where k='owners_page3')),4,'last owner page contains the remainder');
select is((select count(distinct item->>'id') from po_evidence e cross join lateral jsonb_array_elements(e.v->'items') item where e.k in('owners_page1','owners_page2','owners_page3')),24::bigint,'ordered owner pages have no overlap or omission');
select is((select v->'items'->0->>'id' from po_evidence where k='owners_page1'),pg_temp.po_id(50)::text,'owner pages follow deterministic display-name ordering');
select is(jsonb_array_length(public.ai_agent_personal_credential_api_v1('owners','{"pageSize":15}')->'items'),15,'fifteen-row owner pages are supported');
select is(jsonb_array_length(public.ai_agent_personal_credential_api_v1('owners','{"pageSize":20}')->'items'),20,'twenty-row owner pages are supported');
select is(public.ai_agent_personal_credential_api_v1('owners','{"page":4}') ,'{"items":[],"total":24,"page":4,"pageSize":10}'::jsonb,'empty owner page retains the exact response contract');
insert into po_evidence values('personal2',pg_temp.po_issue(2,1002)),('personal3',pg_temp.po_issue(3,1003));
insert into po_evidence values('issue_replay',pg_temp.po_issue(2,1002)),('issued_list',public.ai_agent_personal_credential_api_v1('list','{"page":1,"pageSize":10}'));
select is((select v->>'credentialKind' from po_evidence where k='personal2'),'personal','issued key is explicitly personal');
select is((select v->>'ownerProfileId' from po_evidence where k='personal2'),pg_temp.po_id(2)::text,'owner identity is the selected current teacher');
select is((select v->>'issuerProfileId' from po_evidence where k='personal2'),pg_temp.po_id(1)::text,'issuer remains separate from owner');
select is((select v->>'ownerName' from po_evidence where k='personal2'),'Synthetic personal owner 2','first issue includes owner display metadata');
select is((select v->>'issuerName' from po_evidence where k='personal2'),'Synthetic personal owner 1','first issue includes issuer display metadata');
select is((select v->'token' from po_evidence where k='issue_replay'),'null'::jsonb,'same-key issuance readback never returns the token');
select is((select v->>'total' from po_evidence where k='issued_list'),'2','admin sees its issued personal metadata');
select throws_ok($q$select pg_temp.po_issue(4,1004)$q$,'42501','ai_agent_forbidden','staff cannot be a teacher-key owner');
select throws_ok($q$select pg_temp.po_issue(7,1007)$q$,'42501','ai_agent_forbidden','banned teacher cannot own a new key');
select throws_ok($q$select pg_temp.po_issue(8,1008)$q$,'42501','ai_agent_forbidden','deleted teacher cannot own a new key');
select throws_ok($q$select public.ai_agent_personal_credential_api_v1('create','{"label":"missing owner","scopes":[],"grant":{},"idempotencyKey":"aa050000-0000-4000-8000-000000009999"}')$q$,'22023','ai_agent_invalid','missing owner cannot silently become a central key');
insert into po_evidence values('central',public.ai_agent_credential_api_v1('create',jsonb_build_object('label','Synthetic central worker','scopes',jsonb_build_array('ai-agent:requests:read','ai-agent:requests:claim','ai-agent:requests:update','chat:outbox:read','chat:send'),'grant',jsonb_build_object('queues',jsonb_build_array('employee_requests'),'actions',jsonb_build_array('read','claim','renew','progress','question','done'),'spaceKeys',jsonb_build_array('space_1'),'purposes',jsonb_build_array('ai_completion')),'expiresAt',null,'idempotencyKey',pg_temp.po_id(1101))));
select is(public.ai_agent_credential_api_v1('list','{}')->>'total','1','legacy metadata list excludes every personal key');
select throws_ok($q$select public.ai_agent_credential_api_v1('revoke',jsonb_build_object('id',(select v->>'id' from po_evidence where k='personal2'),'idempotencyKey',pg_temp.po_id(1199)))$q$,'P0002','ai_agent_not_found','legacy revoke cannot select a personal credential');
select throws_ok($q$select dashboard_private.ai_agent_personal_row_allowed_v1(null,null)$q$,'42501',null,'private owner helper is not a client RPC');
reset role;
select ok((select credential_kind='central' and owner_profile_id is null from dashboard_private.ai_agent_credentials where id=(select (v->>'id')::uuid from po_evidence where k='central')),'central issuer keys remain explicitly separate');
select throws_ok($q$update dashboard_private.ai_agent_credentials set owner_profile_id=pg_temp.po_id(3) where id=(select (v->>'id')::uuid from po_evidence where k='personal2')$q$,'55000','ai_agent_immutable','key cannot be reassigned to a different owner');
select throws_ok($q$update dashboard_private.ai_agent_credentials set credential_kind='central',owner_profile_id=null where id=(select (v->>'id')::uuid from po_evidence where k='personal2')$q$,'55000','ai_agent_immutable','personal key cannot be widened into central');
select throws_ok($q$update dashboard_private.ai_agent_credentials set created_by=pg_temp.po_id(2) where id=(select (v->>'id')::uuid from po_evidence where k='personal2')$q$,'55000','ai_agent_immutable','issuer identity is immutable too');
update public.profiles set name='Renamed teacher' where id=pg_temp.po_id(2);
update public.profiles set name='Renamed issuer' where id=pg_temp.po_id(1);
set local role authenticated;
insert into po_evidence values('renamed_list',public.ai_agent_personal_credential_api_v1('list','{}'));
select is(pg_temp.po_item('personal2','renamed_list')->>'ownerName','Renamed teacher','metadata list resolves the current owner display name');
select is(pg_temp.po_item('personal2','renamed_list')->>'issuerName','Renamed issuer','metadata list resolves the current issuer display name');
select ok(pg_temp.po_item('personal2','renamed_list')->>'ownerProfileId'=pg_temp.po_id(2)::text and pg_temp.po_item('personal2','renamed_list')->>'issuerProfileId'=pg_temp.po_id(1)::text,'display rename leaves owner and issuer identities unchanged');
select is(pg_temp.po_issue(2,1002)-'token',(select v-'token' from po_evidence where k='personal2'),'issuance receipt retains its original display metadata without changing authority');
reset role;
update public.profiles set name=null where id in(pg_temp.po_id(1),pg_temp.po_id(2));
set local role authenticated;
insert into po_evidence values('nullable_list',public.ai_agent_personal_credential_api_v1('list','{}'));
select is(pg_temp.po_item('personal2','nullable_list')->'ownerName','null'::jsonb,'missing owner display name remains a mandatory JSON null');
select is(pg_temp.po_item('personal2','nullable_list')->'issuerName','null'::jsonb,'missing issuer display name remains a mandatory JSON null');
reset role;

select set_config('request.jwt.claim.sub',pg_temp.po_id(2)::text,true);
set local role authenticated;
select is(public.ai_agent_personal_credential_api_v1('list','{}')->>'total','1','teacher sees only its owned key metadata');
select throws_ok($q$select public.ai_agent_personal_credential_api_v1('owners','{}')$q$,'42501','ai_agent_forbidden','teacher cannot enumerate other owner candidates through the RPC');
select throws_ok($q$select pg_temp.po_issue(2,1202)$q$,'42501','ai_agent_forbidden','teacher cannot self-issue a key');
select throws_ok($q$select public.ai_agent_personal_credential_api_v1('revoke',jsonb_build_object('id',(select v->>'id' from po_evidence where k='personal3'),'idempotencyKey',pg_temp.po_id(1299)))$q$,'P0002','ai_agent_not_found','teacher cannot revoke another teacher key');
insert into po_evidence values('own',public.ai_agent_user_api_v1('create',jsonb_build_object('title','Owner request','body','Synthetic only','notifyOnDone',true,'notificationSpace','space_1','idempotencyKey',pg_temp.po_id(2002)))),('own_second',public.ai_agent_user_api_v1('create',jsonb_build_object('title','Owner request two','body','Synthetic only','idempotencyKey',pg_temp.po_id(2102))));
reset role;
select set_config('request.jwt.claim.sub',pg_temp.po_id(3)::text,true);
set local role authenticated;
insert into po_evidence values('other',public.ai_agent_user_api_v1('create',jsonb_build_object('title','Other teacher request','body','Synthetic only','notifyOnDone',true,'notificationSpace','space_1','idempotencyKey',pg_temp.po_id(2003))));
reset role;
select set_config('request.jwt.claim.sub',pg_temp.po_id(4)::text,true);
set local role authenticated;
select throws_ok($q$select public.ai_agent_personal_credential_api_v1('list','{}')$q$,'42501','ai_agent_forbidden','staff does not receive personal credential administration');
select throws_ok($q$select public.ai_agent_personal_credential_api_v1('owners','{}')$q$,'42501','ai_agent_forbidden','staff cannot enumerate owner candidates either');
reset role;
select throws_ok($q$update dashboard_private.ai_agent_requests set requester_id=pg_temp.po_id(3) where id=pg_temp.po_request('own')$q$,'55000','ai_agent_immutable','request owner cannot change under a claim or cached receipt');
select throws_ok($q$update dashboard_private.ai_agent_requests set queue_key='different_queue' where id=pg_temp.po_request('own')$q$,'55000','ai_agent_immutable','request queue identity cannot change either');

set local role service_role;
select is(jsonb_array_length(pg_temp.po_bot('personal2','list','{"limit":1}')->'items'),1,'owned filter is applied before the first-page limit');
select ok((select bool_and(x->>'requesterId'=pg_temp.po_id(2)::text) from jsonb_array_elements(pg_temp.po_bot('personal2','list')->'items')x),'bot list contains only current owner requests');
select is(pg_temp.po_bot('personal2','get',jsonb_build_object('id',pg_temp.po_request('own')))->>'requesterId',pg_temp.po_id(2)::text,'owned detail is accessible');
select throws_ok($q$select pg_temp.po_bot('personal2','get',jsonb_build_object('id',pg_temp.po_request('other')))$q$,'P0002','ai_agent_not_found','other-owner detail cannot be guessed');
select throws_ok($q$select pg_temp.po_bot('personal2','activity',jsonb_build_object('id',pg_temp.po_request('other')))$q$,'P0002','ai_agent_not_found','other-owner Q&A and timeline are not accessible');
select throws_ok($q$select pg_temp.po_bot('personal2','actions',jsonb_build_object('id',pg_temp.po_request('other')))$q$,'P0002','ai_agent_not_found','other-owner action list is not accessible');
select throws_ok($q$select pg_temp.po_bot('personal2','action_events',jsonb_build_object('id',pg_temp.po_request('other'),'actionId',pg_temp.po_id(2900)))$q$,'P0002','ai_agent_not_found','other-owner action history is not accessible');
select throws_ok($q$select pg_temp.po_bot('personal2','claim',pg_temp.po_claim_input('other',3003))$q$,'P0002','ai_agent_not_found','other-owner claim is rejected before any mutation');
select throws_ok($q$select pg_temp.po_bot('personal2','renew',pg_temp.po_claim_input('other',3013)||jsonb_build_object('claimGeneration','1'))$q$,'P0002','ai_agent_not_found','other-owner renew cannot extend a lease');
select throws_ok($q$select pg_temp.po_bot('personal2','progress',pg_temp.po_claim_input('other',3023)||jsonb_build_object('claimGeneration','1','text','Synthetic'))$q$,'P0002','ai_agent_not_found','other-owner progress cannot append content');
select throws_ok($q$select pg_temp.po_bot('personal2','question',pg_temp.po_claim_input('other',3033)||jsonb_build_object('claimGeneration','1','text','Synthetic'))$q$,'P0002','ai_agent_not_found','other-owner question cannot change the workflow');
select throws_ok($q$select pg_temp.po_bot('personal2','done',pg_temp.po_claim_input('other',3043)||jsonb_build_object('claimGeneration','1','result','Synthetic'))$q$,'P0002','ai_agent_not_found','other-owner completion cannot create a result or outbox');
select is(jsonb_array_length(pg_temp.po_bot('central','list')->'items'),3,'legacy central worker retains its queue behavior');
insert into po_evidence values('claim',pg_temp.po_bot('personal2','claim',pg_temp.po_claim_input('own',3002)));
insert into po_evidence values('renew',pg_temp.po_bot('personal2','renew',pg_temp.po_update_input(3102)));
select is((select v->'claim'->>'generation' from po_evidence where k='claim'),'1','personal claim retains the existing generation protocol');
select is((select v->'request'->>'version' from po_evidence where k='renew'),'2','lease renewal preserves business version');
insert into po_evidence values('question_input',pg_temp.po_update_input(3202)||jsonb_build_object('text','Synthetic question'));
insert into po_evidence values('question',pg_temp.po_bot('personal2','question',(select v from po_evidence where k='question_input')));
select is(pg_temp.po_bot('personal2','question',(select v from po_evidence where k='question_input'))->'request'->>'status','question','same-key question receipt is owned and recoverable');
select throws_ok($q$select pg_temp.po_bot('personal2','register_action',jsonb_build_object('id',pg_temp.po_request('own')))$q$,'42501','ai_agent_action_forbidden','personal key cannot register a business action');
select throws_ok($q$select pg_temp.po_bot('personal2','start_action',jsonb_build_object('id',pg_temp.po_request('own')))$q$,'42501','ai_agent_action_forbidden','personal key cannot start a business action');
select throws_ok($q$select pg_temp.po_bot('personal2','record_action',jsonb_build_object('id',pg_temp.po_request('other')))$q$,'42501','ai_agent_action_forbidden','late domain result path cannot bypass personal isolation');
reset role;
select set_config('request.jwt.claim.sub',pg_temp.po_id(2)::text,true);
set local role authenticated;
insert into po_evidence values('answer',public.ai_agent_user_api_v1('append_message',jsonb_build_object('id',pg_temp.po_request('own'),'version','3','idempotencyKey',pg_temp.po_id(3302),'kind','answer','text','Synthetic answer','questionId',(select v->'message'->>'id' from po_evidence where k='question'))));
select is((select v->'request'->>'status' from po_evidence where k='answer'),'pending','owner answer atomically resumes the pending queue');
reset role;
set local role service_role;
select throws_ok($q$select pg_temp.po_bot('personal2','question',(select v from po_evidence where k='question_input'))$q$,'55000','ai_agent_claim_lost','old question receipt cannot restore an ended generation');
insert into po_evidence values('reclaim',pg_temp.po_bot('personal2','claim',pg_temp.po_claim_input('own',3402,'4')));
insert into po_evidence values('done_input',pg_temp.po_update_input(3502)||jsonb_build_object('result','Synthetic result, no external operation'));
insert into po_evidence values('done',pg_temp.po_bot('personal2','done',(select v from po_evidence where k='done_input')));
select is((select v->'request'->>'status' from po_evidence where k='done'),'done','owner workflow completes with the existing status machine');
select is(pg_temp.po_bot('personal2','done',(select v from po_evidence where k='done_input'))->'request'->>'status','done','same-key done receipt remains recoverable under current ownership');
insert into po_evidence values('other_claim',pg_temp.po_bot('central','claim',pg_temp.po_claim_input('other',3403)));
insert into po_evidence values('other_done',pg_temp.po_bot('central','done',jsonb_build_object('id',pg_temp.po_request('other'),'version','2','idempotencyKey',pg_temp.po_id(3503),'claimTokenHash',repeat('a',64),'claimGeneration','1','result','Synthetic other result')));
reset role;
insert into po_evidence select 'own_outbox',dashboard_private.chat_outbox_json_v1(o) from dashboard_private.chat_delivery_outbox o where request_id=pg_temp.po_request('own');
insert into po_evidence select 'other_outbox',dashboard_private.chat_outbox_json_v1(o) from dashboard_private.chat_delivery_outbox o where request_id=pg_temp.po_request('other');
insert into po_evidence select 'legacy_chat_binding',to_jsonb(encode(sha256(convert_to(jsonb_build_object('operation','chat_list','credentialId',c.id,'spaceKeys',g.space_keys,'purposes',g.purposes,'sourceId',g.bridge_source_id,'state',null::text,'limit',1)::text,'UTF8')),'hex')) from dashboard_private.ai_agent_credentials c join dashboard_private.chat_credential_space_grants g on g.credential_id=c.id where c.id=(select (v->>'id')::uuid from po_evidence where k='central');
select ok((select bool_and(owner_profile_id=pg_temp.po_id(2) and credential_id=(select (v->>'id')::uuid from po_evidence where k='personal2') and issuer_id=pg_temp.po_id(1)) from dashboard_private.ai_agent_request_events where request_id=pg_temp.po_request('own') and actor_kind='bot'),'audit stores bot credential, owner, and issuer separately');

set local role service_role;
insert into po_evidence values('central_chat_page',pg_temp.po_chat('central','list','{"limit":1}'));
select is(convert_from(decode((select v->>'nextCursor' from po_evidence where k='central_chat_page'),'base64'),'UTF8')::jsonb->>'binding',(select v#>>'{}' from po_evidence where k='legacy_chat_binding'),'central Chat cursor retains the exact original grant binding');
select is(jsonb_array_length(pg_temp.po_chat('personal2','list','{"limit":1}')->'items'),1,'outbox owner filter is applied before pagination');
select is(pg_temp.po_chat('personal2','get',jsonb_build_object('id',(select v->>'id' from po_evidence where k='own_outbox')))->'outbox'->>'requestId',pg_temp.po_request('own')::text,'personal key reads its own completion intent');
select throws_ok($q$select pg_temp.po_chat('personal2','get',jsonb_build_object('id',(select v->>'id' from po_evidence where k='other_outbox')))$q$,'P0002','ai_agent_not_found','outbox ID guessing cannot expose another owner');
select throws_ok($q$select pg_temp.po_chat('personal2','prepare_attempt',jsonb_build_object('id',(select v->>'id' from po_evidence where k='other_outbox'),'revision','1','idempotencyKey',pg_temp.po_id(4103)))$q$,'P0002','ai_agent_not_found','another owner completion cannot be dispatched');
select throws_ok($q$select public.ai_agent_chat_bridge_grant_v1(pg_temp.po_hash('personal2'))$q$,'42501','ai_agent_grant_forbidden','personal key cannot use the public bridge helper');
select throws_ok($q$select pg_temp.po_chat('personal2','chat_outbox','{}')$q$,'42501','ai_agent_grant_forbidden','personal key cannot create a bridge intent');
insert into po_evidence values('prepare_input',jsonb_build_object('id',(select v->>'id' from po_evidence where k='own_outbox'),'revision',(select v->>'revision' from po_evidence where k='own_outbox'),'idempotencyKey',pg_temp.po_id(4102)));
insert into po_evidence values('prepared',pg_temp.po_chat('personal2','prepare_attempt',(select v from po_evidence where k='prepare_input')));
select isnt((select v->'attempt' from po_evidence where k='prepared'),'null'::jsonb,'owned prepare produces one durable synthetic attempt');
select is(pg_temp.po_chat('personal2','prepare_attempt',(select v from po_evidence where k='prepare_input'))->'attempt','null'::jsonb,'same prepare key creates zero extra dispatch authorization');
insert into po_evidence values('record_input',jsonb_build_object('id',(select v->'outbox'->>'id' from po_evidence where k='prepared'),'attemptId',(select v->'attempt'->>'attemptId' from po_evidence where k='prepared'),'idempotencyKey',pg_temp.po_id(4202),'outcome','sent','code','200','messageName','spaces/PERSONAL_owner_space/messages/one','threadName','spaces/PERSONAL_owner_space/threads/one'));
insert into po_evidence values('recorded',pg_temp.po_chat('personal2','record_attempt',(select v from po_evidence where k='record_input')));
select is((select v->'outbox'->>'state' from po_evidence where k='recorded'),'sent','synthetic result append preserves durable attempt semantics');
select is(pg_temp.po_chat('personal2','record_attempt',(select v from po_evidence where k='record_input'))->'outbox'->>'state','sent','owned result receipt replays under current authorization');
select is(pg_temp.po_chat('personal2','get',jsonb_build_object('id',(select v->>'id' from po_evidence where k='own_outbox')))->'attempts','[]'::jsonb,'personal outbox read hides provider attempt history');
select is(jsonb_array_length(pg_temp.po_chat('central','get',jsonb_build_object('id',(select v->>'id' from po_evidence where k='own_outbox')))->'attempts'),2,'central get retains its existing attempt history');
select throws_ok($q$select pg_temp.po_chat('personal2','record_attempt',(select v from po_evidence where k='record_input')||jsonb_build_object('id',(select v->>'id' from po_evidence where k='other_outbox')))$q$,'P0002','ai_agent_not_found','late result cannot target a different owner outbox');
reset role;
select ok((select bool_and(owner_profile_id=pg_temp.po_id(2)) from dashboard_private.chat_delivery_attempts where outbox_id=(select (v->>'id')::uuid from po_evidence where k='own_outbox')),'attempt audit keeps the personal owner identity');
update dashboard_private.chat_user_space_permissions set space_keys='{}',revision=revision+1 where user_id=pg_temp.po_id(2);
set local role service_role;
select is(jsonb_array_length(pg_temp.po_chat('personal2','list')->'items'),0,'revoked current space permission hides old completion intents');
select throws_ok($q$select pg_temp.po_chat('personal2','prepare_attempt',(select v from po_evidence where k='prepare_input'))$q$,'42501','ai_agent_space_forbidden','space revocation is checked before prepare receipt replay');
select throws_ok($q$select pg_temp.po_chat('personal2','record_attempt',(select v from po_evidence where k='record_input'))$q$,'42501','ai_agent_space_forbidden','late result receipt cannot bypass current owner space permission');
reset role;
update dashboard_private.chat_user_space_permissions set space_keys=array['space_1'],revision=revision+1 where user_id=pg_temp.po_id(2);
update dashboard_private.chat_space_configuration set configured=false,resource_name=null where space_key='space_1';
set local role service_role;
select throws_ok($q$select pg_temp.po_chat('personal2','record_attempt',(select v from po_evidence where k='record_input'))$q$,'42501','ai_agent_space_forbidden','disabled current configuration rejects result receipt readback');
reset role;
update dashboard_private.chat_space_configuration set configured=true,resource_name='spaces/PERSONAL_owner_space' where space_key='space_1';
update dashboard_private.ai_agent_credential_grants set revoked_at=clock_timestamp() where credential_id=(select (v->>'id')::uuid from po_evidence where k='personal2');
set local role service_role;
select throws_ok($q$select pg_temp.po_bot('personal2','done',(select v from po_evidence where k='done_input'))$q$,'42501','ai_agent_grant_forbidden','AI grant revocation is checked before a done receipt');
reset role;
update dashboard_private.ai_agent_credential_grants set revoked_at=null,expires_at=clock_timestamp()-interval '1 second' where credential_id=(select (v->>'id')::uuid from po_evidence where k='personal2');
set local role service_role;
select throws_ok($q$select pg_temp.po_bot('personal2','done',(select v from po_evidence where k='done_input'))$q$,'42501','ai_agent_grant_forbidden','AI grant expiry is checked before a done receipt');
reset role;
update dashboard_private.ai_agent_credential_grants set expires_at=clock_timestamp()+interval '1 day' where credential_id=(select (v->>'id')::uuid from po_evidence where k='personal2');
update dashboard_private.ai_agent_credentials set scopes=array_remove(scopes,'ai-agent:requests:update') where id=(select (v->>'id')::uuid from po_evidence where k='personal2');
set local role service_role;
select throws_ok($q$select pg_temp.po_bot('personal2','done',(select v from po_evidence where k='done_input'))$q$,'42501','ai_agent_scope_forbidden','removed AI update scope cannot expose cached result');
reset role;
update dashboard_private.ai_agent_credentials set scopes=array_append(scopes,'ai-agent:requests:update'),expires_at=clock_timestamp()-interval '1 second' where id=(select (v->>'id')::uuid from po_evidence where k='personal2');
set local role service_role;
select throws_ok($q$select pg_temp.po_bot('personal2','done',(select v from po_evidence where k='done_input'))$q$,'28000','ai_agent_unauthorized','expired credential cannot replay a done result');
reset role;
update dashboard_private.ai_agent_credentials set expires_at=clock_timestamp()+interval '1 day' where id=(select (v->>'id')::uuid from po_evidence where k='personal2');
