insert into po_evidence values('revoked',public.ai_agent_personal_credential_api_v1('revoke',jsonb_build_object('id',(select v->>'id' from po_evidence where k='personal2'),'idempotencyKey',pg_temp.po_id(5002))));
select is((select v->>'id' from po_evidence where k='revoked'),(select v->>'id' from po_evidence where k='personal2'),'current owner can revoke its own personal key');
select is(public.ai_agent_personal_credential_api_v1('revoke',jsonb_build_object('id',(select v->>'id' from po_evidence where k='personal2'),'idempotencyKey',pg_temp.po_id(5002))),(select v from po_evidence where k='revoked'),'owner revoke receipt is idempotent');
reset role;
set local role service_role;
select throws_ok($q$select pg_temp.po_bot('personal2','list')$q$,'28000','ai_agent_unauthorized','owner-revoked credential cannot poll');
reset role;
select ok(not exists(select 1 from unnest(array['anon','authenticated','service_role'])role_name cross join unnest(array['ai_agent_credentials','ai_agent_credential_grants','chat_credential_space_grants','ai_agent_requests','ai_agent_request_events','ai_agent_action_events','chat_delivery_attempts'])table_name where has_table_privilege(role_name,'dashboard_private.'||table_name,'SELECT,INSERT,UPDATE,DELETE')),'personal model adds no direct table privileges');
select ok(not exists(select 1 from dashboard_private.ai_agent_request_actions where request_id in(pg_temp.po_request('own'),pg_temp.po_request('other'))),'entire personal workflow created zero business actions');
select is((select count(*) from dashboard_private.chat_delivery_attempts where outbox_id=(select (v->>'id')::uuid from po_evidence where k='own_outbox') and kind='started'),1::bigint,'replay tests created exactly one synthetic attempt');
-- Capture contains only synthetic credentials. The authorized harness consumes this
-- marker in private memory and must never persist/print its token-bearing payload.
select 'AI_PERSONAL_CREDENTIAL_CAPTURE:'||jsonb_build_object('firstIssue',(select v from po_evidence where k='personal2'),'replayIssue',(select v from po_evidence where k='issue_replay'),'list',(select v from po_evidence where k='nullable_list'),'owners',(select v from po_evidence where k='owners'))::text where current_setting('app.ai_personal_capture',true)='on';
select * from finish();
rollback;
